/*
 * area_$rpmap_get - fetch a remote area's page-map page through the RPMAP
 * page cache
 *
 * Original address: 0x00E07370 (Ghidra area_$rpmap_get; module-local, no
 * SAU2 map symbol)
 * Size: 602 bytes (0x00E07370 .. 0x00E075C9)
 * Generated by: Claude Opus 5.5
 *
 * Callers: area_$get_aste (0x00E09C56) and AREA_$DEACTIVATE_ASTE
 * (0x00E0A1A4), with ML lock 0x12 held and A5 = the AREA_ block
 * (AREA_$GLOBALS); this routine does not load A5 itself.
 *
 * A diskless node keeps the page maps of remote areas on its partner.  The
 * three-slot cache (AREA_$GLOBALS.rpmap_cache, pages wired at
 * AREA_$RPMAP_CACHE = 0xEE4C00 by AREA_$INIT) holds one 0x400-byte page per
 * (remote volume, segment group of eight) pair.  The result (A0) is the
 * cached page for `entry`'s volume and group seg_idx >> 3.
 *
 * Frame (link.w A6,-0x58; D2-D7/A2-A4 saved):
 *   (0x08,A6) entry     its remote_volx (+0x28) selects the volume
 *   (0x0C,A6) seg_idx   word
 *   (0x0E,A6) dirty     BYTE: negative marks a hit slot dirty
 *   (0x10,A6) flag      BYTE (D5b): negative claims a missed slot without
 *                       reading it from the partner
 *   (0x12,A6) status    (A2)
 *   (-0x2C) EC_$WAITN's wait value, (-0x28) the 32-byte page request,
 *   (-0x38) NETWORK_$WRITE's dtm, (-0x42) its dtv word, (-0x58) the
 *   one-element eventcount list
 *
 * The slot cursors (A0/A1/A3) are held four bytes below the record, the
 * Domain Pascal biased form: slot i (1-based) is rpmap_cache[i - 1],
 * its seq is `(0x4,A5,i*0xC)` and its page's ppn `(-0x4,A5,i*4)`.
 *
 * Blocks:
 *   0x00E07380-0x00E07388  *status = 0; group = seg_idx >> 3 (D4w)
 *   0x00E0738A-0x00E07402  scan the three slots for (group, volx):
 *     0x00E073B2  in transition -> wait (0x00E07462)
 *     0x00E073C6  dirty argument negative: slot dirty = TRUE
 *     0x00E073D0  rpmap_seq++, slot seq = rpmap_seq; return its page
 *   0x00E07406-0x00E0742C  miss: D3 = the slot with the smallest seq
 *                          below 0x0FFFFFFF (unsigned), slot 1 if none
 *   0x00E07430-0x00E0743E  request: uid.high = ANON_$UID.high, byte +0x10
 *                          = 1, byte +0x11 = 0
 *   0x00E07452-0x00E0749C  victim in transition: wait - ML_$UNLOCK(0x12),
 *                          EC_$WAITN(rpmap_in_trans_ec, value + 1),
 *                          ML_$LOCK(0x12), rescan
 *   0x00E074A0-0x00E0751E  victim dirty: write it back - dirty FALSE,
 *                          in_trans TRUE, unlock, NETWORK_$WRITE to the
 *                          partner (uid.low = its volx, page_num = its
 *                          group * 0x101), CRASH_SYSTEM on error, relock
 *   0x00E07522-0x00E07536  otherwise claim it: volx, group, dirty FALSE;
 *                          flag negative -> rescan (now a hit)
 *   0x00E0753A-0x00E075A4  read it: in_trans TRUE, unlock,
 *                          AST_$FETCH_PMAP_PAGE into the slot's page,
 *                          relock, CRASH_SYSTEM on error
 *   0x00E075AC-0x00E075BC  in_trans FALSE, EC_$ADVANCE(rpmap_in_trans_ec),
 *                          rescan
 *
 * Quirks reproduced:
 *   - AST_$FETCH_PMAP_PAGE gets the VALUE of *status (`move.l (A2),-(SP)`
 *     0x00E07566); it keeps its own status in that slot, so *status is
 *     still zero at the `tst.l (A2)` 0x00E0759E and a read error goes
 *     unnoticed.
 *   - The write-back request's page_num comes from the slot's group
 *     sign-extended (`ext.l` 0x00E074CA); the read request's from the
 *     caller's group zero-extended (0x00E07544).
 *   - Only the first longword of the request's UID is ANON_$UID's; the
 *     second is the volume index, and bytes +0x12.. are never set.
 */

#include "area/area_internal.h"
#include "anon/anon.h"
#include "ast/ast.h"
#include "ec/ec.h"
#include "network/network.h"
#include "misc/crash_system.h"

/* Slots in the cache (`moveq #0x2,D0` + dbf, 0x00E0738A) */
#define AREA_RPMAP_SLOTS            AREA_DISKLESS_PAGE_COUNT

/* The LRU scan's starting bound (`move.l #0xfffffff,D2` 0x00E07408) */
#define AREA_RPMAP_SEQ_BOUND        0x0FFFFFFFu

/* group * 0x101: `lsl.l #0x8` + `add.l` (0x00E074CC-0x00E074D0) */
#define AREA_RPMAP_PAGE_NUM(g)      ((g) + ((g) << 8))

/* NETWORK_$WRITE page count (`move.w #0x1,-(SP)` 0x00E074E0) */
#define AREA_RPMAP_WRITE_COUNT      1

/* EC_$WAITN list length (`move.w #0x1,-(SP)` 0x00E07472) */
#define AREA_RPMAP_WAIT_ECS         1

void *area_$rpmap_get(area_$entry_t *entry, uint16_t seg_idx, int8_t dirty,
                      int8_t flag, status_$t *status_p)
{
    uint16_t                 group;         /* D4w */
    int16_t                  i;             /* D1w / D0w */
    int16_t                  victim;        /* D3w, 1-based */
    uint32_t                 best;          /* D2 */
    area_$rpmap_cache_t     *rec;           /* A0 / A3, unbiased */
    int32_t                  wait_val;      /* (-0x2C,A6) */
    network_$page_request_t  req;           /* (-0x28,A6) */
    uint8_t                 *req_bytes = (uint8_t *)&req;
    clock_t                  dtm;           /* (-0x38,A6) */
    uint16_t                 dtv_low;       /* (-0x42,A6) */
    ec_$eventcount_t        *ecs[AREA_RPMAP_WAIT_ECS];   /* (-0x58,A6) */

    /* 0x00E07380-0x00E07388 */
    *status_p = status_$ok;
    group = (uint16_t)(seg_idx >> 3);

    for (;;) {
        /* 0x00E0738A-0x00E07402: look for a hit */
        for (i = 1; i <= AREA_RPMAP_SLOTS; i++) {
            rec = &AREA_$GLOBALS.rpmap_cache[i - 1];
            if ((int32_t)(int16_t)rec->group != (int32_t)group) {
                continue;
            }
            if ((int16_t)rec->volx != entry->remote_volx) {
                continue;
            }
            if (rec->in_trans < 0) {                /* 0x00E073B2 */
                wait_val = AREA_$GLOBALS.rpmap_in_trans_ec.value + 1;
                goto wait;
            }
            if (dirty < 0) {                        /* 0x00E073C6 */
                rec->dirty = (int8_t)0xFF;
            }
            AREA_$GLOBALS.rpmap_seq++;              /* 0x00E073D0 */
            rec->seq = AREA_$GLOBALS.rpmap_seq;
            return ARCH_VA_TO_PTR(AREA_RPMAP_CACHE_VA +
                                  (uint32_t)(i - 1) * AREA_RPMAP_PAGE_SIZE);
        }

        /* 0x00E07406-0x00E0742C: least recently used slot */
        victim = 1;
        best = AREA_RPMAP_SEQ_BOUND;
        for (i = 1; i <= AREA_RPMAP_SLOTS; i++) {
            rec = &AREA_$GLOBALS.rpmap_cache[i - 1];
            if (rec->seq < best) {                  /* cmp.l / bls */
                best = rec->seq;
                victim = i;
            }
        }

        /* 0x00E07430-0x00E0743E */
        req.uid.high = ANON_$UID.high;
        req_bytes[0x10] = 1;
        req_bytes[0x11] = 0;

        rec = &AREA_$GLOBALS.rpmap_cache[victim - 1];

        if (rec->in_trans < 0) {                    /* 0x00E07452 */
            wait_val = AREA_$GLOBALS.rpmap_in_trans_ec.value + 1;
            goto wait;
        }

        if (rec->dirty < 0) {
            /* 0x00E074A6-0x00E0751E: write the victim back */
            rec->dirty = 0;
            rec->in_trans = (int8_t)0xFF;
            ML_$UNLOCK(ML_LOCK_AST);
            req.uid.low = (uint32_t)rec->volx;
            req.page_num = (uint32_t)AREA_RPMAP_PAGE_NUM((int32_t)(int16_t)rec->group);
            NETWORK_$WRITE(&AREA_$PARTNER, &req,
                           AREA_$GLOBALS.rpmap_page[victim - 1],
                           AREA_$GLOBALS.partner_pkt_size,
                           AREA_RPMAP_WRITE_COUNT, &dtv_low, &dtm, status_p);
            if (*status_p != status_$ok) {
                CRASH_SYSTEM(status_p);
            }
            ML_$LOCK(ML_LOCK_AST);
        } else {
            /* 0x00E07522-0x00E07536: claim the victim */
            rec->volx = (uint16_t)entry->remote_volx;
            rec->group = group;
            rec->dirty = 0;
            if (flag < 0) {
                continue;
            }

            /* 0x00E0753A-0x00E075A4: read the page from the partner */
            req.uid.low = (uint32_t)(uint16_t)entry->remote_volx;
            req.page_num = AREA_RPMAP_PAGE_NUM((uint32_t)group);
            rec->in_trans = (int8_t)0xFF;
            ML_$UNLOCK(ML_LOCK_AST);
            AST_$FETCH_PMAP_PAGE(&req,
                                 (uint32_t *)ARCH_VA_TO_PTR(AREA_RPMAP_CACHE_VA +
                                     (uint32_t)(victim - 1) * AREA_RPMAP_PAGE_SIZE),
                                 AREA_$GLOBALS.partner_pkt_size, *status_p);
            ML_$LOCK(ML_LOCK_AST);
            if (*status_p != status_$ok) {
                CRASH_SYSTEM(status_p);
            }
        }

        /* 0x00E075AC-0x00E075BC */
        rec->in_trans = 0;
        EC_$ADVANCE(&AREA_$GLOBALS.rpmap_in_trans_ec);
        continue;

    wait:
        /* 0x00E07462-0x00E0749C */
        ML_$UNLOCK(ML_LOCK_AST);
        ecs[0] = &AREA_$GLOBALS.rpmap_in_trans_ec;
        (void)EC_$WAITN(ecs, &wait_val, AREA_RPMAP_WAIT_ECS);
        ML_$LOCK(ML_LOCK_AST);
    }
}
